/* Shared, content-free clock. Mini copy is generated by sync-usage-clock.mjs. */
;(function (root) {
  function create(env) {
    const time=()=>Math.floor(env.now()/1000)*1000;
    let feature='', identity='', visit='', visible=false;
    let last=time(), lastTouch=last;
    function tick() {
      const now=time(), elapsed=now-last;
      if (!visible || !identity || !feature || elapsed<0 || elapsed>60000) { last=now; return }
      const seconds=Math.floor(elapsed/1000);
      if (!seconds) return;
      const end=last+seconds*1000;
      while(last<end){
        const midnight=(Math.floor((last+28800000)/86400000)+1)*86400000-28800000;
        const boundary=Math.min(end,midnight), foreground=(boundary-last)/1000;
        const active=Math.min(foreground,Math.max(0,Math.floor((lastTouch+120000-last)/1000)));
        env.emit({identity,eventId:env.uuid(),visitId:visit,featureKey:feature,
          startedAt:new Date(last).toISOString(),endedAt:new Date(boundary).toISOString(),
          foregroundSeconds:foreground,activeSeconds:active});
        last=boundary;
      }
    }
    function select(nextFeature,nextIdentity) {
      if (identity!==nextIdentity) { last=time();identity=nextIdentity;feature=''; }
      if (feature===nextFeature) return;
      tick();feature=nextFeature;visit=env.uuid();last=time();lastTouch=last;
    }
    function visibility(next) {
      if (next===visible) return;
      tick();visible=next;last=time();
      if (next) lastTouch=last;
    }
    function touch(){tick();lastTouch=time()}
    return {tick,select,visibility,touch};
  }
  const api={create};
  if (typeof module!=='undefined' && module.exports) module.exports=api;
  else root.KGUsageClock=api;
})(typeof globalThis!=='undefined'?globalThis:this);
